// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 0);

        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        vm.prank(bob);
        c.addToBalance{value: 0}();

        Reentrance fresh = new Reentrance();
        address alice2 = address(0xdead);
        vm.deal(alice2, 1 ether);

        vm.prank(alice2);
        fresh.addToBalance{value: 1}();

        bool ok;
        try fresh.addToBalance{value: 2}() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
